EMERGENCY_MESSAGE='⚠️ This may be a medical emergency. Do not rely on this AI assessment. Contact your local emergency service or go to the nearest emergency department immediately.'
PATTERNS={"chest pain/pressure":["chest pain","chest pressure","severe chest pain","सीने में दर्द","सीने में दबाव","seene mein dard"],"severe breathing difficulty":["severe breathing","difficulty breathing","can't breathe","cannot breathe","saans nahi aa","saans lene mein bahut dikkat","सांस नहीं आ रही"],"stroke-like symptoms":["face droop","one side weakness","slurred speech","stroke","chehra tedha","ek taraf kamzori","bolne mein dikkat"],"loss of consciousness":["unconscious","loss of consciousness","fainted","बेहोश","behosh","behoshi"],"severe bleeding":["severe bleeding","heavy bleeding","bleeding won't stop","bahut khoon","khoon nahi ruk"],"seizure":["seizure","convulsion","दौरा","fits aa rahe","mirgi ka daura"],"severe allergic reaction":["anaphylaxis","throat swelling","face swelling with breathing","gala band","saans ke saath allergy"],"severe poisoning":["poisoning","overdose","zeher","poison kha liya","overdose ho gaya"],"sudden severe headache":["worst headache","sudden severe headache","achanak bahut tez sir dard","thunderclap headache"],"severe abdominal pain":["severe abdominal pain","severe stomach pain","pet mein bahut tez dard"],"self-harm emergency":["kill myself","suicide","self harm","marna chahta","khud ko nuksan","suicide karna"]}
def detect_emergency(text:str)->list[str]:
    t=(text or '').lower(); return [label for label,terms in PATTERNS.items() if any(term in t for term in terms)]
def apply_safety(result:dict,symptoms:str)->dict:
    flags=detect_emergency(symptoms)
    if flags: result.update({"risk_level":"Emergency","red_flags":flags,"recommended_action":EMERGENCY_MESSAGE,"otc_information":[],"doctor_required":True,"emergency":True}); result['safety_note']='Do not delay emergency medical care. This AI cannot assess an emergency reliably.'
    return result
